const contracts=[{"id": "00", "slug": "00-charge", "title": "電荷、單位與力", "control": {"id": "lab-input", "name": "q", "label": "試驗電荷 q", "unit": "nC", "type": "range", "min": -5, "max": 5, "step": 0.5, "default": 3}}, {"id": "01", "slug": "01-vectors", "title": "向量、座標與投影", "control": {"id": "lab-input", "name": "theta", "label": "向量與 +x 的夾角 θ", "unit": "°", "type": "range", "min": 0, "max": 180, "step": 5, "default": 60}}, {"id": "02", "slug": "02-calculus", "title": "微積分、通量與場的短橋", "control": {"id": "lab-input", "name": "length", "label": "盒子的 x 向長度 L", "unit": "m", "type": "range", "min": 0.1, "max": 1, "step": 0.1, "default": 0.5}}, {"id": "03", "slug": "03-coulomb", "title": "庫侖定律與疊加", "control": {"id": "lab-input", "name": "radius", "label": "源電荷到觀測點 r", "unit": "m", "type": "range", "min": 0.1, "max": 0.5, "step": 0.01, "default": 0.3}}, {"id": "04", "slug": "04-distributions", "title": "連續電荷與積分", "control": {"id": "lab-input", "name": "height", "label": "環軸觀測高度 z", "unit": "m", "type": "range", "min": 0, "max": 0.5, "step": 0.01, "default": 0.1}}, {"id": "05", "slug": "05-gauss", "title": "高斯定律與對稱", "control": {"id": "lab-input", "name": "radius", "label": "距離長直線電荷 r", "unit": "m", "type": "range", "min": 0.02, "max": 0.3, "step": 0.01, "default": 0.1}}, {"id": "06", "slug": "06-potential", "title": "電位、梯度與電偶極", "control": {"id": "lab-input", "name": "radius", "label": "距離正點電荷 r", "unit": "m", "type": "range", "min": 0.05, "max": 0.5, "step": 0.01, "default": 0.2}}, {"id": "07", "slug": "07-conductors", "title": "導體、屏蔽與邊值問題", "control": {"id": "lab-input", "name": "position", "label": "板間 x 位置", "unit": "mm", "type": "range", "min": 0, "max": 6, "step": 0.5, "default": 3}}, {"id": "08", "slug": "08-dielectrics", "title": "介電質與電場邊界", "control": {"id": "lab-input", "name": "epsr", "label": "介質2相對介電常數 εr2", "unit": "", "type": "range", "min": 1, "max": 10, "step": 0.5, "default": 4}}, {"id": "09", "slug": "09-capacitance", "title": "電容、能量與幾何", "control": {"id": "lab-input", "name": "gap", "label": "板距 d", "unit": "mm", "type": "range", "min": 0.5, "max": 5, "step": 0.1, "default": 1}}, {"id": "10", "slug": "10-current", "title": "電流密度、導電與連續性", "control": {"id": "lab-input", "name": "current", "label": "銅線電流 I", "unit": "A", "type": "range", "min": 0, "max": 5, "step": 0.1, "default": 1}}, {"id": "11", "slug": "11-lorentz", "title": "羅倫茲力與磁偶極", "control": {"id": "lab-input", "name": "angle", "label": "速度與磁場夾角 θ", "unit": "°", "type": "range", "min": 0, "max": 180, "step": 5, "default": 90}}, {"id": "12", "slug": "12-magnetostatics", "title": "畢歐—沙伐與安培定律", "control": {"id": "lab-input", "name": "current", "label": "長直線電流 I", "unit": "A", "type": "range", "min": 0, "max": 20, "step": 1, "default": 10}}, {"id": "13", "slug": "13-magnetic-media", "title": "磁性材料、磁路與邊界", "control": {"id": "lab-input", "name": "current", "label": "線圈電流 I", "unit": "A", "type": "range", "min": 0, "max": 0.5, "step": 0.01, "default": 0.2}}, {"id": "14", "slug": "14-vector-potential", "title": "磁向量位", "control": {"id": "lab-input", "name": "position", "label": "觀測位置 x", "unit": "m", "type": "range", "min": 0, "max": 1, "step": 0.05, "default": 0.3}}, {"id": "15", "slug": "15-induction", "title": "法拉第、冷次與動生電動勢", "control": {"id": "lab-input", "name": "speed", "label": "滑動棒速度 v", "unit": "m/s", "type": "range", "min": 0, "max": 6, "step": 0.5, "default": 3}}, {"id": "16", "slug": "16-inductance", "title": "自感、互感與變壓器", "control": {"id": "lab-input", "name": "current", "label": "線圈電流 I", "unit": "A", "type": "range", "min": 0, "max": 4, "step": 0.1, "default": 2}}, {"id": "17", "slug": "17-maxwell", "title": "位移電流與馬克士威方程式", "control": {"id": "lab-input", "name": "slew", "label": "電壓上升率 dV/dt", "unit": "MV/s", "type": "range", "min": 0, "max": 5, "step": 0.1, "default": 1}}, {"id": "18", "slug": "18-waves", "title": "波動方程與坡印廷能流", "control": {"id": "lab-input", "name": "amplitude", "label": "電場峰值 E0", "unit": "V/m", "type": "range", "min": 0, "max": 200, "step": 5, "default": 100}}, {"id": "19", "slug": "19-phasors", "title": "相量與偏振", "control": {"id": "lab-input", "name": "phase", "label": "Ey相對Ex相位 δ", "unit": "°", "type": "range", "min": -180, "max": 180, "step": 15, "default": 90}}, {"id": "20", "slug": "20-lossy-media", "title": "損耗介質與皮深", "control": {"id": "lab-input", "name": "frequency", "label": "銅中頻率 f", "unit": "MHz", "type": "range", "min": 0.1, "max": 10, "step": 0.1, "default": 1}}, {"id": "21", "slug": "21-normal-incidence", "title": "垂直入射、反射與功率", "control": {"id": "lab-input", "name": "epsr", "label": "介質2相對介電常數 εr2", "unit": "", "type": "range", "min": 1, "max": 9, "step": 0.5, "default": 4}}, {"id": "22", "slug": "22-oblique-incidence", "title": "折射、TE/TM 與全反射", "control": {"id": "lab-input", "name": "angle", "label": "玻璃到空氣入射角 θi", "unit": "°", "type": "range", "min": 0, "max": 80, "step": 1, "default": 30}}, {"id": "23", "slug": "23-transmission-lines", "title": "分佈傳輸線與行波", "control": {"id": "lab-input", "name": "length", "label": "線長 ℓ", "unit": "m", "type": "range", "min": 0.1, "max": 10, "step": 0.1, "default": 2}}, {"id": "24", "slug": "24-standing-waves", "title": "駐波、輸入阻抗與史密斯圖", "control": {"id": "lab-input", "name": "load", "label": "純電阻負載 RL", "unit": "Ω", "type": "range", "min": 0, "max": 200, "step": 5, "default": 100}}, {"id": "25", "slug": "25-matching-transients", "title": "匹配與暫態反射", "control": {"id": "lab-input", "name": "load", "label": "待匹配電阻 RL", "unit": "Ω", "type": "range", "min": 25, "max": 200, "step": 5, "default": 100}}, {"id": "26", "slug": "26-waveguides", "title": "波導與諧振腔一窺", "control": {"id": "lab-input", "name": "frequency", "label": "空氣矩形波導頻率 f", "unit": "GHz", "type": "range", "min": 4, "max": 15, "step": 0.1, "default": 10}}, {"id": "27", "slug": "27-antennas", "title": "天線與輻射一窺", "control": {"id": "lab-input", "name": "frequency", "label": "天線設計頻率 f", "unit": "MHz", "type": "range", "min": 100, "max": 1000, "step": 10, "default": 300}}];
'use strict';
const EPS0=8.8541878128e-12, MU0=1.25663706212e-6, C0=299792458, ETA0=376.7303137, K=8.9875517923e9;
const rad=x=>x*Math.PI/180;
const fmt=x=> typeof x==='string'?x: !Number.isFinite(x)?'∞':x===0?'0':Math.abs(x)>=1e5||Math.abs(x)<.0001?x.toExponential(4):Number(x.toPrecision(6)).toString();
function calculate(id,x){
 id=String(id).padStart(2,'0');let m={},primary=0,unit='',why='',status='模型範圍內';
 const add=(key,label,value,u)=>{m[key]={label,value,unit:u};};
 switch(id){
 case'00':{const f=x*1e-9*2000;add('force','x向電力 F',f*1e6,'μN');primary=f*1e6;unit='μN';why=`F=qE：電場固定向 +x，電荷 ${fmt(x)} nC ${x<0?'帶負號，力轉向 −x':x===0?'為零，力也為零':'帶正號，力沿 +x'}；大小隨電荷量成正比。`;break;}
 case'01':{const ax=5*Math.cos(rad(x)),ay=5*Math.sin(rad(x));add('ax','x投影 Ax',Math.abs(ax)<1e-12?0:ax,'N');add('ay','y投影 Ay',Math.abs(ay)<1e-12?0:ay,'N');add('magnitude','原向量大小',5,'N');primary=m.ax.value;unit='N';why=`Ax=5 cos(${fmt(x)}°)。角度跨過 90°，x 投影由正變負；Ax²+Ay²=25 N²，改投影不改原來 5 N 的大小。`;break;}
 case'02':{const flux=100*x*.02;add('flux','淨向外通量 Φ',flux,'V·m');add('divergence','散度 ∇·E',100,'V/m²');add('endfield','右端 Ex',100*x,'V/m');primary=flux;unit='V·m';why=`右面場 100×${fmt(x)} V/m 乘面積 0.02 m²；左面 x=0 場為零，其餘面點積為零。盒子加長容納更多淨源，Φ=散度×體積。`;break;}
 case'03':{const e=K*2e-9/x**2;add('field','向外電場 E',e,'V/m');add('force','對 +1 nC 的力',e*.001,'μN');primary=e;unit='V/m';why=`E=kq/r²；距離 ${fmt(x)} m 在分母平方，距離加倍使同一電荷的場降至四分之一。力沿源電荷指向觀測點的方向。`;break;}
 case'04':{const e=K*1e-8*x/(.01+x*x)**1.5;add('field','環軸電場 Ez',e,'V/m');add('distance','各電荷元距離',Math.sqrt(.01+x*x),'m');primary=e;unit='V/m';why=`環上相反側的橫向分量相消，只留 z 分量。z=${fmt(x)} m 時 Ez=kQz/(a²+z²)^(3/2)；中心 z=0 為零，遠處又因距離變大而減弱。`;break;}
 case'05':{const e=2e-9/(2*Math.PI*EPS0*x);add('field','徑向電場 E',e,'V/m');add('flux','每米高圓柱的通量',2e-9/EPS0,'V·m');primary=e;unit='V/m';why=`圓柱側面面積為 2πr×1 m。包住的每米電荷固定，r=${fmt(x)} m 增加時相同通量攤到更大側面，E 隨 1/r 下降。`;break;}
 case'06':{const v=K*2e-9/x,e=K*2e-9/x**2;add('potential','以無限遠為零的 V',v,'V');add('field','徑向場 E',e,'V/m');primary=v;unit='V';why=`V=kq/r，對 r 微分再加負號便得 Er=−dV/dr=kq/r²。距離 ${fmt(x)} m 越遠，正電荷的電位越低，場指向電位下降方向。`;break;}
 case'07':{const v=12*x/6;add('potential','位置電位 V',v,'V');add('field','板間 Ex',-2000,'V/m');primary=v;unit='V';why=`無體電荷讓 d²V/dx²=0，邊界 0 V 與 12 V 使 V=2000x（x用m）。位置 ${fmt(x)} mm 的 V 改變，但斜率固定，所以 E=−2000 V/m。`;break;}
 case'08':{const en=8/x,sigma=EPS0*(en-4),angle=Math.atan2(3,en)*180/Math.PI;add('e2t','E2 切向',3,'V/m');add('e2n','E2 法向',en,'V/m');add('dnormal','兩側 D 法向',8*EPS0*1e12,'pC/m²');add('sigma','淨束縛面電荷',sigma*1e12,'pC/m²');add('angle','E2 與 +z 法線夾角',angle,'°');primary=en;unit='V/m';why=`ρsf=0 固定 D2n=D1n=8ε0；εr2=${fmt(x)} 越大，E2n=8/εr2 越小。E2t 一直是 3 V/m；D 的切向可以改變，沒有自由面電荷不等於沒有束縛面電荷。`;break;}
 case'09':{const c=3*EPS0*.01/(x*1e-3),q=c*10,u=.5*c*100;add('capacitance','電容 C',c*1e12,'pF');add('charge','板上電荷量 Q',q*1e9,'nC');add('energy','儲能 U',u*1e9,'nJ');primary=c*1e12;unit='pF';why=`固定接上 10 V 電源：板距 ${fmt(x)} mm 越小，C=εA/d 越大，電源再供電荷讓 Q=CV 增加，儲能也隨 C 增加。這與斷開電源固定 Q 的情境不同。`;break;}
 case'10':{const r=2/(5.8e7*1e-6);add('resistance','導線 R',r,'Ω');add('voltage','端電壓 V',x*r,'V');add('power','焦耳熱功率 P',x*x*r,'W');add('density','電流密度 J',x*1e6,'A/m²');primary=x*x*r;unit='W';why=`截面與導電率固定，R=${fmt(r)} Ω。I=${fmt(x)} A 時每秒損失 I²R 的能量為熱；電流加倍使熱功率四倍，並不是消耗掉电荷。`.replace('电','電');break;}
 case'11':{const f=2e-9*3e5*.2*Math.sin(rad(x));add('force','磁力大小',Math.abs(f)<1e-16?0:f*1e6,'μN');add('magneticPower','磁力做功率',0,'W');primary=m.force.value;unit='μN';why=`叉積只取速度垂直 B 的部分：F=qvB sin(${fmt(x)}°)。平行時為零，90°最大；磁力總與瞬時速度垂直，所以 F·v=0。`;break;}
 case'12':{const b=MU0*x/(2*Math.PI*.02);add('field','距軸 2 cm 的 B',b*1e6,'μT');add('hfield','環向 H',x/(2*Math.PI*.02),'A/m');primary=b*1e6;unit='μT';why=`安培迴路半徑不變，B×2πr=μ0I。電流 ${fmt(x)} A 加大時繞線的 B 等比例增加；方向用右手定則，+z 電流在 +x 點產生 +y 磁場。`;break;}
 case'13':{const h=100*x/.2,b=MU0*500*h;add('hfield','磁場強度 H',h,'A/m');add('field','磁通密度 B',b,'T');add('flux','磁通 Φ',b*1e-4*1e6,'μWb');primary=b;unit='T';why=`磁動勢 NI=${fmt(100*x)} A·turn 驅動封閉磁路；在 μr=500 的線性假設下 B=μNI/ℓ。實際材料接近飽和時不會再照這條直線增加。`;break;}
 case'14':{add('potential','向量位 Ay',.2*x,'Wb/m');add('field','旋度 Bz',.2,'T');primary=.2*x;unit='Wb/m';why=`Ay=0.2x 隨位置 ${fmt(x)} m 線性增加；Bz 看的是 Ay 的空間斜率 ∂Ay/∂x=0.2 T，因此向量位數值不同仍可給相同磁場。`;break;}
 case'15':{const emf=.5*.2*x,i=emf/2,force=.5*i*.2;add('emf','動生電動勢 ε',emf,'V');add('current','電流大小 I',i,'A');add('force','反向磁阻力大小',force,'N');add('power','外力供能率',force*x,'W');primary=emf;unit='V';why=`棒速度 ${fmt(x)} m/s 使掃過面積率 ℓv 增加，|ε|=Bℓv。感應電流的磁力反向阻擋運動，外力機械功率 Fv=I²R，能量流入電阻成熱。`;break;}
 case'16':{const flux=.02*x,energy=.5*.02*x*x;add('linkage','磁鏈 λ',flux,'Wb·turn');add('energy','儲磁能 U',energy,'J');primary=energy;unit='J';why=`線性電感 L=0.020 H 固定，磁鏈 λ=LI；建立到 ${fmt(x)} A 需要 U=∫Li di=LI²/2 的能量，電流加倍而儲能四倍。`;break;}
 case'17':{const c=EPS0*.01/.001,idis=c*x*1e6;add('capacitance','真空電容 C',c*1e12,'pF');add('current','位移電流 Id',idis*1e6,'μA');primary=idis*1e6;unit='μA';why=`上升率 ${fmt(x)} MV/s 改變板間 D=ε0V/d，Id=∂∫D·dS/∂t=C dV/dt。它与导線電流同值，卻不是自由電荷穿過真空间隙。`.replace('与','與').replace('导','導').replace('空间','空間');break;}
 case'18':{const h=x/ETA0,s=x*x/(2*ETA0);add('hfield','磁場峰值 H0',h,'A/m');add('powerDensity','時間平均能流',s,'W/m²');primary=s;unit='W/m²';why=`+z 行波的 E 沿 x、H 沿 y，E×H 指向 +z。峰值 E0=${fmt(x)} V/m 時平均 cos²=1/2，故 ⟨S⟩=E0²/(2η0)，不是 E0²/η0。`;break;}
 case'19':{const ex=3/Math.sqrt(2),ey=3*Math.cos(Math.PI/4+rad(x));add('ex','t=T/8 的 Ex',ex,'V/m');add('ey','t=T/8 的 Ey',Math.abs(ey)<1e-12?0:ey,'V/m');add('phase','相對相位 δ',x,'°');primary=m.ey.value;unit='V/m';const a=Math.abs(x);status=a===90?'圓偏振':a===0||a===180?'線偏振':'橢圓偏振';why=`同點兩分量各有 3 V/m 峰值；相位差 ${fmt(x)}° 改變先後次序，而不是改變傳播方向。此時 ${status}；圖中依 t=0、T/8、T/4 標示端點順序。`;break;}
 case'20':{const delta=Math.sqrt(2/(2*Math.PI*x*1e6*MU0*5.8e7));add('depth','皮深 δ',delta*1e6,'μm');add('alpha','衰減常數 α≈β',1/delta,'1/m');add('ratio','σ/(ωε0)',5.8e7/(2*Math.PI*x*1e6*EPS0),'');primary=delta*1e6;unit='μm';why=`良導體條件 σ≫ωε 下，δ=√(2/ωμσ)。頻率 ${fmt(x)} MHz 越高，場在更薄的一層內就衰減到表面振幅的 1/e；能流衰減是振幅平方。`;break;}
 case'21':{const eta=ETA0/Math.sqrt(x),gamma=(eta-ETA0)/(eta+ETA0),tau=1+gamma,r=gamma*gamma,t=ETA0/eta*tau*tau;add('gamma','電場反射係數 Γ',gamma,'');add('transmitted','透射電場峰值',10*tau,'V/m');add('reflectance','功率反射率 R',r,'');add('transmittance','功率透射率 T',t,'');primary=gamma;unit='';why=`εr2=${fmt(x)} 使 η2=η0/√εr2。Γ=(η2−η1)/(η2+η1)；負號代表反射 E 相位反轉。功率還須乘阻抗比，R+T=${fmt(r+t)}，不能把振幅平方直接當 T。`;break;}
 case'22':{const s=1.5*Math.sin(rad(x)),critical=Math.asin(1/1.5)*180/Math.PI;add('critical','臨界角 θc',critical,'°');add('snell','1.5 sin θi',s,'');if(s>1){primary=null;unit='°';status='全反射；沒有實數透射角';add('thetaT','透射角','無實數角','');why=`1.5 sin(${fmt(x)}°)=${fmt(s)}>1，不可硬取反正弦。法向傳播常數變虛數，空氣側仍有倏逝場；理想無耗損單界面不把淨平均功率送向法線遠方。`;}else{primary=Math.asin(s)*180/Math.PI;unit='°';add('thetaT','透射角 θt',primary,'°');why=`沿介面相位一致要求 n1 sinθi=n2 sinθt，故 θt=asin(1.5 sin ${fmt(x)}°)。從高折射率進低折射率，透射線離法線更遠；到 θc≈41.8103° 變成掠射。`;}break;}
 case'23':{const z=Math.sqrt(250e-9/100e-12),v=1/Math.sqrt(250e-9*100e-12);add('impedance','特性阻抗 Z0',z,'Ω');add('velocity','行波速度 v',v,'m/s');add('delay','单程延遲 td'.replace('单','單'),x/v*1e9,'ns');primary=x/v*1e9;unit='ns';why=`每米 L′、C′ 決定 Z0=50 Ω 与 v=2×10⁸ m/s；線長 ${fmt(x)} m 只改變傳播所需 td=ℓ/v，不把 Z0 當成隨線長累加的直流電阻。`.replace('与','與');break;}
 case'24':{const gamma=(x-50)/(x+50),vl=3*(1+gamma),il=3*(1-gamma)/50,pr=.09*gamma*gamma,pl=.09-pr,vswr=Math.abs(gamma)===1?'∞':(1+Math.abs(gamma))/(1-Math.abs(gamma));add('gamma','負載反射係數 Γ',gamma,'');add('reflected','反射電壓峰值 V−',3*gamma,'V');add('voltage','負載電壓峰值 VL',vl,'V');add('current','負載電流峰值 IL',il,'A');add('incidentPower','入射平均功率',.09,'W');add('reflectedPower','反射平均功率',pr,'W');add('loadPower','負載平均功率',pl,'W');add('vswr','電壓駐波比',vswr,'');primary=vl;unit='V';why=`RL=${fmt(x)} Ω 要滿足 VL=RL·IL，反射電流相對 +z 帶負號。Γ=${fmt(gamma)} 使 VL=${fmt(vl)} Vpeak、IL=${fmt(il)} Apeak；平均功率 0.09−${fmt(pr)}=${fmt(pl)} W 流入負載。${x===0?'短路電壓為零且全反射，VSWR 為∞。':x===50?'匹配時沒有反射，包絡是水平線。':''}`;break;}
 case'25':{const zt=Math.sqrt(50*x),zin=zt*zt/x;add('transformer','四分之一波段 Zt',zt,'Ω');add('input','設計頻率的 Zin',zin,'Ω');primary=zt;unit='Ω';why=`在長度恰為 λ/4 的設計頻率，Zin=Zt²/RL；選 Zt=√(50×${fmt(x)}) Ω 把輸入變成 50 Ω。改頻率會改電氣長度，這不是所有頻率都有效的匹配。`;break;}
 case'26':{const fc=C0/(2*.02286),f=x*1e9;add('cutoff','TE10 截止頻率 fc',fc/1e9,'GHz');if(f<=fc||Math.abs(f-fc)<=fc*1e-12){const atCutoff=Math.abs(f-fc)<=fc*1e-12;primary=null;unit='mm';status=atCutoff?'精確截止：β=0，導波波長發散':'低於截止：沒有實數導波波長';add('wavelength','導波波長 λg',atCutoff?'發散（∞）':'不適用','');add('attenuation','倏逝衰減常數',atCutoff?0:2*Math.PI/C0*Math.sqrt(fc*fc-f*f),'1/m');why=atCutoff?'f=fc 時 β=0、α=0，λg 趨向無限大，沒有沿 z 的相位推進；此精確邊界不能說成正的指數衰減。':`f=${fmt(x)} GHz 低於 fc，β 不是正實數，場沿波導指數衰減，不能以實數 λg 描述行進波。`;}else{const beta=2*Math.PI/C0*Math.sqrt(f*f-fc*fc),lambda=2*Math.PI/beta;primary=lambda*1e3;unit='mm';add('wavelength','導波波長 λg',lambda*1e3,'mm');add('groupVelocity','群速度 vg',C0*Math.sqrt(1-(fc/f)**2),'m/s');why=`f=${fmt(x)} GHz 高於 fc，β=(2π/c)√(f²−fc²)。靠近截止時 β 小、λg 大；相速度可大於 c，承載訊息的群速度仍小於 c。`;}break;}
 case'27':{const lambda=C0/(x*1e6);add('wavelength','自由空間波長 λ',lambda,'m');add('length','理想半波總長 ℓ',lambda/2,'m');primary=lambda/2;unit='m';why=`f=${fmt(x)} MHz 使 λ=c/f，半波天線總長約 λ/2。頻率加倍，幾何長度約減半；實際導線有端效應與周遭物體，需用網路分析儀調整，不能把理想長度當保證。`;break;}
 }
 const primaryKey=['force','ax','flux','field','field','field','potential','potential','e2n','capacitance','power','force','field','field','potential','emf','energy','current','powerDensity','ey','depth','gamma','thetaT','delay','voltage','transformer','wavelength','length'][Number(id)];
 return{id,input:x,metrics:m,primary,primaryKey,unit,why,status};
}
function graph(id,x,result){
 const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
 const title=`${contracts[Number(id)].title}：參數與物理結果`;
 let s=`<title id="lab-plot-title">${esc(title)}</title><desc id="lab-plot-desc">${esc(result.why)}</desc><defs><marker id="lab-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#203a4b"/></marker></defs>`;
 const tx=(a,b,t,extra='')=>`<text x="${a}" y="${b}" font-size="15" fill="#203a4b" ${extra}>${esc(t)}</text>`;
 if(id==='08'){
 const en=result.metrics.e2n.value;
 s+=`<rect x="20" y="25" width="600" height="140" fill="#e6f2f3"/><path d="M20 165H620" stroke="#203a4b" stroke-width="2"/><path d="M580 240V55" stroke="#203a4b" stroke-width="2" marker-end="url(#lab-arrow)"/>`+tx(535,45,'+z，n：1→2')+tx(32,55,`介質2 εr2=${fmt(x)}`)+tx(32,190,'介質1 εr1=2')+tx(32,285,'兩箭頭同尺度：12圖單位 = 1 V/m');
 s+=`<path d="M140 250L176 202" stroke="#006c78" stroke-width="4" marker-end="url(#lab-arrow)"/><path d="M140 250H176V202" stroke="#006c78" stroke-dasharray="5 4" fill="none"/><path d="M370 145L406 ${145-en*12}" stroke="#bd6513" stroke-width="4" marker-end="url(#lab-arrow)"/><path d="M370 145H406V${145-en*12}" stroke="#bd6513" stroke-dasharray="5 4" fill="none"/><circle class="current-point" data-x="${x}" data-y="${en}" cx="406" cy="${145-en*12}" r="5"/>`+tx(188,220,'E1：3x̂ + 4ẑ V/m')+tx(315,28,`E2：3x̂ + ${fmt(en)}ẑ V/m`)+tx(324,165,'切向都為 3 V/m')+tx(32,265,`Dn 相同：${fmt(result.metrics.dnormal.value)} pC/m²`);
 }else if(id==='24'){
 const g=result.metrics.gamma.value,points=[];
 for(let i=0;i<=160;i++){const z=-1+i/160,a=3*Math.sqrt(1+g*g+2*g*Math.cos(4*Math.PI*z));points.push(`${60+i/160*530},${245-a/6*195}`);}
 s+=`<path d="M60 35V245H602" stroke="#203a4b" fill="none"/><polyline points="${points.join(' ')}" fill="none" stroke="#006c78" stroke-width="3"/><circle class="current-point" data-x="${x}" data-y="${result.primary}" cx="590" cy="${245-result.primary/6*195}" r="6"/>`+tx(10,25,'|V|（Vpeak）')+tx(500,288,'z/λ（負載0）')+tx(48,268,'−1')+tx(314,268,'−0.5')+tx(583,268,'0')+tx(34,249,'0')+tx(34,54,'6')+tx(185,28,`最大 ${fmt(3*(1+Math.abs(g)))} V；最小 ${fmt(3*(1-Math.abs(g)))} V`)+tx(90,285,`|V(z)|，Γ=${fmt(g)}，VSWR=${fmt(result.metrics.vswr.value)}`);
 }else if(id==='19'){
 const points=[];for(let i=0;i<=160;i++){const t=i/160*2*Math.PI;points.push(`${320+100*Math.cos(t)},${150+100*Math.cos(t+rad(x))}`);}
 s+=`<path d="M140 150H500" stroke="#73888d" marker-end="url(#lab-arrow)"/><path d="M320 30V265" stroke="#73888d" marker-end="url(#lab-arrow)"/><polyline points="${points.join(' ')}" stroke="#006c78" stroke-width="3" fill="none"/>`+tx(500,150,'Ex（V/m）')+tx(335,258,'+Ey 向下（V/m）');
 [0,Math.PI/4,Math.PI/2].forEach((t,i)=>{const px=320+100*Math.cos(t),py=150+100*Math.cos(t+rad(x));s+=`<circle ${i===1?`class="current-point" data-x="${x}" data-y="${result.primary}"`:''} cx="${px}" cy="${py}" r="6" fill="#bd6513"/>`+tx(px+10,py-5,['t=0','T/8','T/4'][i]);});s+=tx(30,288,`${result.status}；固定 z=0 朝 +z 看；+x 向右、+y 向下，時間依標記增加`);
 }else{
 const c=contracts[Number(id)].control,values=[];const count=Math.round((c.max-c.min)/c.step);for(let i=0;i<=count;i++){const a=Number((c.min+c.step*i).toPrecision(12)),r=calculate(id,a);values.push({x:a,y:r.primary});}values.push({x,y:result.primary});values.sort((a,b)=>a.x-b.x);
 const finite=values.filter(a=>a.y!==null&&Number.isFinite(a.y));let lo=Math.min(0,...finite.map(a=>a.y)),hi=Math.max(0,...finite.map(a=>a.y));if(lo===hi)hi=lo+1;const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const px=a=>65+(a-c.min)/(c.max-c.min)*525,py=a=>235-(a-lo)/(hi-lo)*185;
 let path='',live=false;for(const v of values){if(v.y===null||!Number.isFinite(v.y)){live=false;continue;}path+=`${live?'L':'M'}${px(v.x).toFixed(2)} ${py(v.y).toFixed(2)} `;live=true;}
 s+=`<path d="M65 35V235H600" stroke="#203a4b" fill="none"/><path d="${path}" stroke="#006c78" stroke-width="3" fill="none"/>`+tx(12,25,`${result.metrics[result.primaryKey]?.label||'觀察量'}（${result.unit||'無因次'}）`)+tx(55,255,fmt(c.min))+tx(565,255,fmt(c.max))+tx(75,282,`${c.label}（${c.unit||'無因次'}）`)+tx(5,55,fmt(hi-pad))+tx(5,232,fmt(lo+pad));
 if(result.primary!==null&&Number.isFinite(result.primary)){s+=`<circle class="current-point" data-x="${x}" data-y="${result.primary}" cx="${px(x)}" cy="${py(result.primary)}" r="6"/>`+tx(280,25,`現在：${fmt(result.primary)} ${result.unit}`);}else{s+=tx(280,25,id==='22'?'全反射：無實數透射角':'截止：無行進波波長');}
 }
 return s;
}
function initialize(){
 const nav=document.querySelector('.course-nav');if(nav){const page=document.body.dataset.page;nav.innerHTML='<nav aria-label="章節導覽"><a href="index.html">課程地圖</a><a href="glossary.html">名詞字典</a><a href="sources.html">教材來源</a>'+contracts.map(c=>`<a class="chapter-link${c.slug===page?' current-chapter':''}" href="${c.slug}.html"${c.slug===page?' aria-current="page"':''}>${c.id} ${c.title}</a>`).join('')+'</nav>';}
 const lab=document.querySelector('[data-lab]');if(lab){const id=lab.dataset.lab.padStart(2,'0'),c=contracts[Number(id)]?.control,input=document.getElementById('lab-input');if(c&&input){const update=()=>{let x=input.value.trim()===''?c.default:Number(input.value);if(!Number.isFinite(x))x=c.default;x=Math.min(c.max,Math.max(c.min,x));x=Math.min(c.max,Math.max(c.min,c.min+Math.round((x-c.min)/c.step)*c.step));x=Number(x.toPrecision(12));input.value=String(x);const r=calculate(id,x);document.getElementById('lab-value').textContent=`${fmt(x)} ${c.unit}`;document.getElementById('lab-results').innerHTML=Object.entries(r.metrics).map(([key,v])=>`<div class="readout" data-key="${key}" data-value="${v.value}"><small>${v.label}</small><strong>${fmt(v.value)} ${v.unit}</strong></div>`).join('');document.getElementById('lab-why').textContent=r.why;const plot=document.getElementById('lab-plot');plot.innerHTML=graph(id,x,r);plot.setAttribute('aria-labelledby','lab-plot-title lab-plot-desc');document.getElementById('lab-description').textContent=`${c.label}=${fmt(x)} ${c.unit}。${r.status}。${id==='08'?'圖上兩側 E 使用相同比例，虛線是切向/法向分解。':id==='24'?'曲線為沿線的電壓振幅包絡；右端 z=0 是負載。':id==='19'?'端點軌跡顯示一週期電場方向；標記列出時間順序。':'曲線掃過允許的控制量範圍，圓點是目前輸入與觀察量；兩軸不是空間座標。'}`;};input.addEventListener('input',update);input.addEventListener('change',update);document.getElementById('lab-reset').addEventListener('click',()=>{input.value=c.default;update();});update();}}
 const search=document.getElementById('glossary-search');if(search){search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let n=0;document.querySelectorAll('.term').forEach(t=>{const visible=t.textContent.toLowerCase().includes(q);t.hidden=!visible;if(visible)n++;});document.getElementById('term-count').textContent=`顯示 ${n} 個條目`;});}
}
if(typeof window!=='undefined'){window.EMLab={calculate,contracts,graph};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initialize);else initialize();}
if(typeof module!=='undefined')module.exports={calculate,contracts,graph};
